"""Parse INI text."""
sections: dict[str, dict[str, str]] = {}
section = None
key = None  # the key a continuation line would extend
for lineno, line in enumerate(text.splitlines(), start=1):
    stripped = line.strip()
    if not stripped or stripped[0] in "#;":
        key = None
        continue
    if key is not None and line[0].isspace():
        section[key] += "\n" + stripped
        continue
    key = None
    if stripped.startswith("[") and stripped.endswith("]"):
        section = sections.setdefault(stripped[1:-1].strip(), {})
        continue
    split = min((i for i in (stripped.find("="), stripped.find(":")) if i >= 0),
                default=-1)
    if split < 0:
        raise ParseError(lineno, f"expected a section or key: {stripped!r}")
    name = stripped[:split].strip().lower()
    if not name:
        raise ParseError(lineno, "empty key")
    if section is None:
        raise ParseError(lineno, f"key {name!r} before any section")
    section[name] = stripped[split + 1:].strip()
    key = name

resolved: dict[tuple[str, str], str] = {}

def resolve(section_name: str, key: str, stack: tuple) -> str:
    ref = (section_name, key)
    if ref in resolved:
        return resolved[ref]
    if ref in stack:
        chain = " -> ".join(f"{s}:{k}" for s, k in stack + (ref,))
        raise InterpolationError(f"interpolation cycle: {chain}")
    if section_name not in sections:
        raise InterpolationError(f"no section {section_name!r}")
    if key not in sections[section_name]:
        raise InterpolationError(f"no key {key!r} in section {section_name!r}")
    value = sections[section_name][key]
    out = []
    i = 0
    while i < len(value):
        if value.startswith("$$", i):
            out.append("$")
            i += 2
            continue
        end = value.find("}", i + 2)
        if value.startswith("${", i) and end >= 0:
            target, colon, target_key = value[i + 2:end].rpartition(":")
            target = target.strip() if colon else section_name
            out.append(resolve(target, target_key.strip().lower(), stack + (ref,)))
            i = end + 1
            continue
        out.append(value[i])
        i += 1
    resolved[ref] = "".join(out)
    return resolved[ref]

return {
    name: {key: resolve(name, key, ()) for key in keys}
    for name, keys in sections.items()
}

